  const links = document.querySelectorAll('a');
  const headlines = [];
  for (const link of links) {
    const text = link.textContent.trim();
    if (text.includes('Warriors, Curry') || text.includes('Indiana loses RB') || text.includes('White Sox')) {
      headlines.push({ text: text.substring(0, 120), href: link.href });
    }
  }
  return headlines;
}()"}

